/** Ultimate weapons and their plus upgrades. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { bullets, heading, sections, table } from '../render.mjs'

/** Chart labels carry line breaks for layout; a page wants the name on one line. */
const oneLine = text => String(text).replace(/\s+/g, ' ').trim()

export function build(context) {
  const { data, charts } = context.sdk
  const { format } = context
  const weapons = Object.values(data.uwStoneChartData)

  for (const weapon of weapons) {
    context.page(
      `Ultimate Weapon: ${weapon.name}`,
      sections(
        ...weapon.stats.map(stat =>
          sections(
            heading(2, stat.name),
            table(['Level', 'Value', 'Stone cost'], stat.levels.map(row => [row.level, row.value, format.cost(row.cost)])),
          ),
        ),
        `Back to ${context.link('Ultimate Weapons')}.`,
      ),
      { source: 'uwStoneChartData' },
    )
  }

  context.page(
    'Ultimate Weapons',
    sections(
      context.overview('ultimate-weapons'),
      table(
        ['Weapon', 'Upgrade tracks'],
        weapons.map(weapon => [context.link(`Ultimate Weapon: ${weapon.name}`, weapon.name), weapon.stats.map(stat => stat.name).join(', ')]),
      ),
      `See also ${context.link('Ultimate Weapon Plus')}.`,
    ),
    { source: 'uwStoneChartData' },
  )

  context.page(
    'Ultimate Weapon Plus',
    sections(
      context.overview('uw-plus'),
      heading(2, 'Unlock Cost'),
      table(['Plus upgrades already owned', 'Stone cost'], Object.entries(charts.uwPlusUnlockCostsByOwnedCount)),
      `Total to unlock all: ${charts.uwPlusUnlockTotal} stones.`,
      ...charts.uwPlusUpgradeSections.flatMap(section =>
        section.upgrades.map(upgrade =>
          sections(
            heading(2, `${oneLine(upgrade.name)}: ${oneLine(upgrade.next)}`),
            upgrade.desc,
            table(['Level', 'Value', 'Stone cost'], Object.entries(upgrade.tiers).map(([level, tier]) => [level, tier.value, tier.cost])),
          ),
        ),
      ),
      heading(2, 'Notes'),
      bullets(charts.uwPlusFooterText.map(line => line.replace(/^\*\s*/, ''))),
      `Back to ${context.link('Ultimate Weapons')}.`,
    ),
    { source: ['uwPlusUpgradeSections', 'uwPlusUnlockCostsByOwnedCount'], entry: '@beardedunicorn/thetowersdk/charts' },
  )

  context.group('Ultimate Weapons', ['Ultimate Weapons', 'Ultimate Weapon Plus'])
}
